SELECT act.activity_id, md.chembl_id AS molecule_chembl_id, td.chembl_id AS target_chembl_id, td.pref_name AS target_name, act.standard_type, act.standard_value, act.standard_units FROM activities act JOIN molecule_dictionary md ON act.molregno = md.molregno JOIN assays a ON act.assay_id = a.assay_id JOIN target_dictionary td ON a.tid = td.tid WHERE td.organism = 'Homo sapiens' AND td.target_type = 'SINGLE PROTEIN' AND act.standard_units = 'nM' AND act.standard_type IN ('EC50', 'IC50', 'AC50') AND act.standard_value < 50 ORDER BY act.activity_id ASC LIMIT 200
